import React, { useState, useEffect, useCallback } from 'react';
import { Auth } from 'aws-amplify';
import { useNavigate } from 'react-router-dom';
import {
    Box,
    Button,
    TextField,
    Typography,
    Container,
    Paper,
    Alert,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions
} from '@mui/material';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [showNewPasswordDialog, setShowNewPasswordDialog] = useState(false);
    const [newPassword, setNewPassword] = useState('');
    const [confirmNewPassword, setConfirmNewPassword] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [user, setUser] = useState(null);
    const navigate = useNavigate();

    const checkAuth = useCallback(async () => {
        try {
            const user = await Auth.currentAuthenticatedUser();
            if (user) {
                navigate('/users');
            }
        } catch (err) {
            console.log('No hay sesión activa');
        }
    }, [navigate]);

    useEffect(() => {
        checkAuth();
    }, [checkAuth]);

    const handleNewPasswordSubmit = async () => {
        if (newPassword !== confirmNewPassword) {
            setPasswordError('Las contraseñas no coinciden');
            return;
        }

        if (newPassword.length < 8) {
            setPasswordError('La contraseña debe tener al menos 8 caracteres');
            return;
        }

        setLoading(true);
        setPasswordError('');

        try {
            const loggedUser = await Auth.completeNewPassword(
                user,
                newPassword,
                {
                    email: user.attributes.email,
                    name: user.attributes.name
                }
            );
            console.log('Contraseña actualizada:', loggedUser);
            setShowNewPasswordDialog(false);
            navigate('/users');
        } catch (err) {
            console.error('Error al actualizar contraseña:', err);
            setPasswordError(err.message || 'Error al actualizar la contraseña');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            // Intentar iniciar sesión
            const loggedUser = await Auth.signIn(username, password);
            console.log('Login exitoso:', loggedUser);

            // Verificar si se requiere nueva contraseña
            if (loggedUser.challengeName === 'NEW_PASSWORD_REQUIRED') {
                setUser(loggedUser);
                setShowNewPasswordDialog(true);
                return;
            }

            // Si no se requiere nueva contraseña, continuar con el flujo normal
            const currentUser = await Auth.currentAuthenticatedUser();
            console.log('Usuario actual:', currentUser);

            if (currentUser) {
                const session = await Auth.currentSession();
                console.log('Sesión actual:', session);

                const token = session.getIdToken().getJwtToken();
                if (token) {
                    console.log('Token obtenido correctamente');
                    localStorage.setItem('token', token);
                    navigate('/users');
                } else {
                    throw new Error('Token no válido');
                }
            } else {
                throw new Error('No se pudo obtener el usuario actual');
            }
        } catch (err) {
            console.error('Error en login:', err);
            if (err.code === 'UserNotConfirmedException') {
                setError('Usuario no confirmado. Por favor, verifica tu email.');
            } else if (err.code === 'NotAuthorizedException') {
                setError('Credenciales incorrectas');
            } else if (err.code === 'UserNotFoundException') {
                setError('Usuario no encontrado');
            } else if (err.code === 'InvalidParameterException') {
                setError('Parámetros de autenticación inválidos');
            } else {
                setError(err.message || 'Error al iniciar sesión');
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <Container component="main" maxWidth="xs">
            <Box
                sx={{
                    marginTop: 8,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                }}
            >
                <Paper elevation={3} sx={{ p: 4, width: '100%' }}>
                    <Typography component="h1" variant="h5" align="center" gutterBottom>
                        Iniciar Sesión
                    </Typography>
                    {error && (
                        <Alert severity="error" sx={{ mb: 2 }}>
                            {error}
                        </Alert>
                    )}
                    <Box component="form" onSubmit={handleSubmit} sx={{ mt: 1 }}>
                        <TextField
                            margin="normal"
                            required
                            fullWidth
                            id="username"
                            label="Usuario"
                            name="username"
                            autoComplete="username"
                            autoFocus
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            disabled={loading}
                        />
                        <TextField
                            margin="normal"
                            required
                            fullWidth
                            name="password"
                            label="Contraseña"
                            type="password"
                            id="password"
                            autoComplete="current-password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            disabled={loading}
                        />
                        <Button
                            type="submit"
                            fullWidth
                            variant="contained"
                            sx={{ mt: 3, mb: 2 }}
                            disabled={loading}
                        >
                            {loading ? 'Iniciando sesión...' : 'Ingresar'}
                        </Button>
                    </Box>
                </Paper>
            </Box>

            {/* Diálogo para nueva contraseña */}
            <Dialog open={showNewPasswordDialog} onClose={() => !loading && setShowNewPasswordDialog(false)}>
                <DialogTitle>Establecer Nueva Contraseña</DialogTitle>
                <DialogContent>
                    <Typography variant="body2" sx={{ mb: 2 }}>
                        Por favor, establece una nueva contraseña para tu cuenta.
                    </Typography>
                    {passwordError && (
                        <Alert severity="error" sx={{ mb: 2 }}>
                            {passwordError}
                        </Alert>
                    )}
                    <TextField
                        margin="normal"
                        required
                        fullWidth
                        name="newPassword"
                        label="Nueva Contraseña"
                        type="password"
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        disabled={loading}
                    />
                    <TextField
                        margin="normal"
                        required
                        fullWidth
                        name="confirmNewPassword"
                        label="Confirmar Nueva Contraseña"
                        type="password"
                        value={confirmNewPassword}
                        onChange={(e) => setConfirmNewPassword(e.target.value)}
                        disabled={loading}
                    />
                </DialogContent>
                <DialogActions>
                    <Button 
                        onClick={() => setShowNewPasswordDialog(false)} 
                        disabled={loading}
                    >
                        Cancelar
                    </Button>
                    <Button 
                        onClick={handleNewPasswordSubmit} 
                        variant="contained"
                        disabled={loading}
                    >
                        {loading ? 'Actualizando...' : 'Actualizar Contraseña'}
                    </Button>
                </DialogActions>
            </Dialog>
        </Container>
    );
};

export default Login;
